//! HEq (heterogeneous equality) type initialization for Environment.
//!
//! Registers the HEq inductive type and all derived declarations:
//! - HEq.rec, HEq.casesOn, HEq.recOn (auto-generated by inductive machinery)
//! - HEq.rfl, heq_of_eq, eq_of_heq (Eq/HEq bridge)
//! - HEq.ndrec, HEq.ndrecOn, HEq.symm, HEq.trans (transport)

mod bridge;
mod context;
mod transport;

use super::EnvError;
use super::Environment;
use context::HeqCtx;

impl Environment {
    /// Initialize HEq (heterogeneous equality) inductive type and derived lemmas.
    ///
    /// Safe to call multiple times (subsequent calls are no-ops).
    ///
    /// # Contract
    ///
    /// REQUIRES: `init_eq()` called (auto-initialized if not)
    /// ENSURES: On success, `self.has_heq() == true`
    /// ENSURES: Idempotent
    pub fn init_heq(&mut self) -> Result<(), EnvError> {
        if self.heq_init {
            return Ok(());
        }

        if !self.eq_init {
            self.init_eq()?;
        }

        let ctx = HeqCtx::new();

        bridge::register(self, &ctx)?;
        transport::register(self, &ctx)?;

        self.heq_init = true;

        // Parameterized inductives use the v4.30 heterogeneous noConfusion
        // scheme, whose generated pair references HEq, HEq.refl, and
        // eq_of_heq. A lightweight environment may have registered such an
        // inductive before HEq existed: init_eq's retry still has to skip it.
        // Now that the complete HEq surface is installed, retry canonical pair
        // generation and grant neither member authority unless both exact
        // declarations pass strict checks.
        self.regenerate_missing_no_confusion();
        Ok(())
    }

    /// Check if HEq type has been initialized.
    #[allow(dead_code)] // Used by test assertions; dead in non-test builds
    pub(crate) fn has_heq(&self) -> bool {
        self.heq_init
    }
}
